}

function buildPath(key) {
  return `root['${escapePathKey(key)}']`;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

export function DeepDiff(left, right) {
  const printable = {};
  const deltaPrintable = {};
  const addedValues = {};
  const changedValues = {};

  for (const key of Object.keys(right)) {
    if (!hasOwn(left, key)) {
      const path = buildPath(key);
      addedValues[path] = right[key];
    }
  }

  for (const key of Object.keys(left)) {
    if (!hasOwn(right, key)) {
      continue;
    }

    if (left[key] !== right[key]) {
      const path = buildPath(key);
      changedValues[path] = {
        new_value: right[key],
        old_value: left[key],
      };
    }
  }

  if (Object.keys(addedValues).length > 0) {
    printable.dictionary_item_added = Object.keys(addedValues);
    deltaPrintable.dictionary_item_added = addedValues;
  }

  if (Object.keys(changedValues).length > 0) {
    printable.values_changed = changedValues;

    const deltaChanges = {};
    for (const [path, value] of Object.entries(changedValues)) {
      deltaChanges[path] = { new_value: value.new_value };
    }
    deltaPrintable.values_changed = deltaChanges;
  }

  return {
    printable,
    [DIFF_DATA]: deltaPrintable,
  };
}

