import { formatPython } from './format.mjs';

const PROGRAM_NAME = 'test15_executable';
const REQUIRED_OPTIONS = ['--a', '--b', '--c'];
const KNOWN_OPTIONS = new Set(['-h', '--help', '--a', '--b', '--c']);
const INTEGER_PATTERN = /^[+-]?\d(?:_?\d)*$/;
const NEGATIVE_NUMBER_PATTERN =
  /^-(?:\d(?:_?\d)*(?:\.\d(?:_?\d)*)?|\.\d(?:_?\d)*)(?:[eE][+-]?\d+)?$/;

function usageText() {
  return `usage: ${PROGRAM_NAME} [-h] --a A --b B --c C`;
}

export function helpText() {
  return `${usageText()}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C`;
}

function errorResult(message) {
  return {
    kind: 'error',
    code: 2,
    text: `${usageText()}\n${PROGRAM_NAME}: error: ${message}`,
  };
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function canBeConsumedAsValue(token) {
  if (token === undefined) {
    return false;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  // argparse treats option-looking tokens as missing values unless they look
  // like negative numbers.
  return isNegativeNumberLike(token);
}

function parseInteger(rawValue, optionName) {
  if (!INTEGER_PATTERN.test(rawValue)) {
    return errorResult(`argument ${optionName}: invalid int value: ${formatPython(rawValue)}`);
  }

  return {
    kind: 'ok',
    value: BigInt(rawValue.replaceAll('_', '')),
  };
}

export function parseArgs(argv) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        text: helpText(),
      };
    }

    if (token === '--a' || token === '--b' || token === '--c') {
      const rawValue = argv[index + 1];

      if (!canBeConsumedAsValue(rawValue)) {
        return errorResult(`argument ${token}: expected one argument`);
      }

      index += 1;

      if (token === '--a') {
        values.a = rawValue;
        continue;
      }

      const parsedInteger = parseInteger(rawValue, token);
      if (parsedInteger.kind === 'error') {
        return parsedInteger;
      }

      if (token === '--b') {
        values.b = parsedInteger.value;
      } else {
        values.c = parsedInteger.value;
      }

      continue;
    }

    if (token.startsWith('-')) {
      extras.push(token);

      const nextToken = argv[index + 1];
      if (canBeConsumedAsValue(nextToken)) {
        extras.push(nextToken);
        index += 1;
      }

      continue;
    }

    extras.push(token);
  }

  const missing = REQUIRED_OPTIONS.filter((optionName) => {
    if (optionName === '--a') {
      return !Object.prototype.hasOwnProperty.call(values, 'a');
    }

    if (optionName === '--b') {
      return !Object.prototype.hasOwnProperty.call(values, 'b');
    }

    return !Object.prototype.hasOwnProperty.call(values, 'c');
  });

  if (missing.length > 0) {
    return errorResult(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    return errorResult(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    kind: 'ok',
    code: 0,
    values,
  };
}

