function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function choosePythonQuote(text) {
  if (text.includes("'") && !text.includes('"')) {
    return '"';
  }

  return "'";
}

function escapePythonString(text, quote) {
  let result = '';

  for (const character of text) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      result += '\\\\';
    } else if (character === quote) {
      result += `\\${quote}`;
    } else if (character === '\n') {
      result += '\\n';
    } else if (character === '\r') {
      result += '\\r';
    } else if (character === '\t') {
      result += '\\t';
    } else if (codePoint < 32 || codePoint === 127) {
      result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
    } else {
      result += character;
    }
  }

  return `${quote}${result}${quote}`;
}

export function formatPython(value) {
  if (typeof value === 'string') {
    const quote = choosePythonQuote(value);
    return escapePythonString(value, quote);
  }

  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPython(item)).join(', ')}]`;
  }

  if (isPlainObject(value)) {
    const parts = Object.entries(value).map(
      ([key, itemValue]) => `${formatPython(key)}: ${formatPython(itemValue)}`,
    );
    return `{${parts.join(', ')}}`;
  }

  throw new TypeError(`Unsupported value type: ${typeof value}`);
}

export function formatJsonLike(value) {
  if (typeof value === 'string') {
    return JSON.stringify(value);
  }

  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }

  if (value === null) {
    return 'null';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatJsonLike(item)).join(', ')}]`;
  }

  if (isPlainObject(value)) {
    const parts = Object.entries(value).map(
      ([key, itemValue]) => `${JSON.stringify(key)}: ${formatJsonLike(itemValue)}`,
    );
    return `{${parts.join(', ')}}`;
  }

  throw new TypeError(`Unsupported value type: ${typeof value}`);
}

